<?php $auth=app(\App\Services\AuthService::class); ?>
<div class="dash-head"><div><h1>Grants</h1><p class="sub">Grant register and user assignments. No financial awards or disbursements are recorded here.</p></div><?php if ($auth->canAny(['grants.create','grants.manage'])): ?><a class="btn btn-brand" href="<?= e(base_url('admin/grants/create')) ?>">Create grant</a><?php endif; ?></div>
<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Grant</th><th>Status</th><th>Assignments</th></tr></thead><tbody><?php foreach ($grants as $g): ?><tr><td><a href="<?= e(base_url('admin/grants/'.(int)$g['id'])) ?>"><?= e($g['reference']) ?></a></td><td><?= e($g['title']) ?></td><td><?= e($g['status']) ?></td><td><?= $auth->canAny(['grant_assignments.view','grant_assignments.manage']) ? (int)$g['assigned_count'] : 'Restricted' ?></td></tr><?php endforeach; ?></tbody></table></div><?php if ($grants===[]): ?><p class="text-muted">No grants have been registered. No earlier grant records were found in this application.</p><?php endif; ?></section>
